const STORAGE_KEY="cafe-bpx-state-v5";
const SUPABASE_URL = "https://ffetxaxymwogckmgdrao.supabase.co";
const SUPABASE_PUBLISHABLE_KEY = "sb_publishable_PmRGBEsztpIfUBu53rFQCw_7FMrdlEg";
const SUPABASE_TABLE = "coffees";
const DEFAULT_COFFEES=[
  {id:1,name:"Espresso",image:"data:image/png;base64,",available:true},
  {id:2,name:"Curto",image:"data:image/png;base64,",available:true},
  {id:3,name:"Duplo",image:"data:image/png;base64,",available:true},
  {id:4,name:"Americano",image:"data:image/png;base64,",available:true},
  {id:5,name:"Cappuccino",image:"data:image/png;base64,",available:true},
  {id:6,name:"Café com leite",image:"data:image/png;base64,",available:true},
  {id:7,name:"Café com leite curto",image:"data:image/png;base64,",available:true},
  {id:8,name:"Nescau com leite",image:"data:image/png;base64,",available:true},
  {id:9,name:"Cappuccino Alpino",image:"data:image/png;base64,",available:true},
  {id:10,name:"Achocolatado Alpino",image:"data:image/png;base64,",available:false},
  {id:11,name:"Mokaccino Dois Frades",image:"data:image/png;base64,",available:false},
  {id:12,name:"Achocolatado Dois Frades",image:"data:image/png;base64,",available:false}
];

const EMPTY_COFFEE_IMAGE = "images/coffee.svg";
let adminData = [];
let pendingCoffeeId = null;
let coffeesCache = null;
let supabaseClient = null;
let realtimeChannel = null;
let refreshTimer = null;

function cloneState(data) { return JSON.parse(JSON.stringify(data)); }

function normalizeUnits(value) {
  const units = Number.parseInt(value, 10);
  return Number.isFinite(units) && units > 0 ? units : 0;
}

function createId() {
  if (globalThis.crypto && crypto.randomUUID) return crypto.randomUUID();
  return `coffee-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value));
}

function findDefaultCoffeeByName(name) {
  return DEFAULT_COFFEES.find(item => item.name.toLocaleLowerCase('pt-BR') === String(name || '').toLocaleLowerCase('pt-BR'));
}

function normalizeCoffee(item, index) {
  const itemName = String(item.name || '').trim();
  const fallback = findDefaultCoffeeByName(itemName) || DEFAULT_COFFEES[index] || {};
  const hasUnits = Object.prototype.hasOwnProperty.call(item, 'units');
  const migratedUnits = item.available ? 100 : 0;

  return {
    id: item.id || fallback.id || createId(),
    name: itemName || fallback.name || '',
    image: item.image || fallback.image || EMPTY_COFFEE_IMAGE,
    units: normalizeUnits(hasUnits ? item.units : migratedUnits),
    created_at: item.created_at || null
  };
}

function getDefaultCoffees() {
  return DEFAULT_COFFEES.map((item, index) => normalizeCoffee(item, index));
}

function getCoffees() {
  const raw = localStorage.getItem(STORAGE_KEY);
  if (!raw) return getDefaultCoffees();

  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return getDefaultCoffees();

    return parsed
      .map((item, index) => normalizeCoffee(item, index))
      .filter(item => item.name);
  } catch {
    return getDefaultCoffees();
  }
}

function saveCoffees(data) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  localStorage.setItem(STORAGE_KEY + ':updatedAt', new Date().toISOString());
}

function cacheCoffees(data) {
  const normalized = data
    .map((item, index) => normalizeCoffee(item, index))
    .filter(item => item.name);
  coffeesCache = cloneState(normalized);
  saveCoffees(normalized);
  return normalized;
}

function getCurrentCoffees() {
  return coffeesCache ? cloneState(coffeesCache) : getCoffees();
}

function getSupabaseClient() {
  if (supabaseClient) return supabaseClient;
  if (!window.supabase || !SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) return null;
  supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY);
  return supabaseClient;
}

async function fetchRemoteCoffees() {
  const client = getSupabaseClient();
  if (!client) return null;

  const { data, error } = await client
    .from(SUPABASE_TABLE)
    .select('id,name,image,units,created_at')
    .order('created_at', { ascending: true });

  if (error) throw error;
  if (!Array.isArray(data) || !data.length) return cacheCoffees(getDefaultCoffees());
  return cacheCoffees(data);
}

async function loadCoffees() {
  try {
    const remote = await fetchRemoteCoffees();
    if (remote) return remote;
  } catch (error) {
    console.warn('Nao foi possivel carregar do Supabase:', error);
  }

  const local = getCoffees();
  coffeesCache = cloneState(local);
  return local;
}

function toRemotePayload(item) {
  const fallback = findDefaultCoffeeByName(item.name);
  const shouldStoreImage = item.image &&
    item.image !== EMPTY_COFFEE_IMAGE &&
    item.image !== fallback?.image &&
    !String(item.image).startsWith('data:image/');

  return {
    name: item.name,
    image: shouldStoreImage ? item.image : '',
    units: normalizeUnits(item.units)
  };
}

async function persistCoffees(data) {
  const normalized = cacheCoffees(data);
  const client = getSupabaseClient();
  if (!client) return normalized;

  const existingRows = normalized
    .filter(item => isUuid(item.id))
    .map(item => ({ id: item.id, ...toRemotePayload(item) }));
  const newRows = normalized
    .filter(item => !isUuid(item.id))
    .map(toRemotePayload);

  if (existingRows.length) {
    const { error } = await client.from(SUPABASE_TABLE).upsert(existingRows, { onConflict: 'id' });
    if (error) throw error;
  }

  if (newRows.length) {
    const { error } = await client.from(SUPABASE_TABLE).insert(newRows);
    if (error) throw error;
  }

  return fetchRemoteCoffees();
}

async function updateCoffeeUnits(coffeeId, units, expectedUnits = null) {
  const client = getSupabaseClient();
  if (!client || !isUuid(coffeeId)) {
    const data = getCurrentCoffees().map(item =>
      String(item.id) === String(coffeeId) ? { ...item, units } : item
    );
    return cacheCoffees(data);
  }

  let query = client
    .from(SUPABASE_TABLE)
    .update({ units: normalizeUnits(units) })
    .eq('id', coffeeId);

  if (expectedUnits !== null) {
    query = query.eq('units', normalizeUnits(expectedUnits));
  }

  const { data, error } = await query.select('id');

  if (error) throw error;
  if (expectedUnits !== null && (!Array.isArray(data) || !data.length)) {
    throw new Error('Estoque atualizado por outro usuario');
  }

  return fetchRemoteCoffees();
}

function getStockText(data) {
  const totalUnits = data.reduce((sum, item) => sum + item.units, 0);
  const available = data.filter(item => item.units > 0).length;
  return `${totalUnits} unidades · ${available} sabores`;
}

function getAvailableText(data) {
  const available = data.filter(item => item.units > 0).length;
  return `${available} de ${data.length} disponíveis`;
}

function formatUpdatedAt() {
  const stored = localStorage.getItem(STORAGE_KEY + ':updatedAt');
  const date = stored ? new Date(stored) : new Date();
  const dd = String(date.getDate()).padStart(2, '0');
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const hh = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  return `Atualizado em ${dd}/${mm}, ${hh}:${min}`;
}

function getLevel(item) {
  const percentage = Math.min(item.units, 100);

  if (item.units <= 10) {
    return { color: '#d84332', label: item.units === 0 ? 'Indisponível' : 'Estoque crítico', percentage };
  }

  if (item.units >= 100) {
    return { color: '#ffc400', label: 'Lotado', percentage: 100 };
  }

  if (item.units <= 35) {
    return { color: '#ffc400', label: 'Estoque baixo', percentage };
  }

  return { color: '#ffc400', label: 'Disponível', percentage };
}

function createThermometer(item) {
  const level = getLevel(item);
  const wrap = document.createElement('div');
  wrap.className = 'stock-thermometer';
  wrap.style.setProperty('--stock-level', `${level.percentage}%`);
  wrap.style.setProperty('--stock-color', level.color);
  wrap.setAttribute('aria-label', `Termômetro do estoque em ${level.percentage} de 100`);

  const scaleTop = document.createElement('span');
  scaleTop.textContent = '100';

  const bar = document.createElement('div');
  bar.className = 'thermo-bar';
  bar.setAttribute('aria-hidden', 'true');

  const fill = document.createElement('span');
  fill.className = 'thermo-fill';
  bar.append(fill);

  const scaleBottom = document.createElement('span');
  scaleBottom.textContent = '0';

  wrap.append(scaleTop, bar, scaleBottom);
  return wrap;
}

function createPublicCard(item) {
  const level = getLevel(item);
  const article = document.createElement('article');
  article.className = `coffee-card ${item.units > 0 ? 'available' : 'unavailable'}`;
  article.style.setProperty('--stock-color', level.color);

  const inner = document.createElement('button');
  inner.className = 'card-button coffee-choice-btn';
  inner.type = 'button';
  inner.disabled = item.units <= 0;
  inner.setAttribute('aria-label', item.units > 0 ? `Escolher ${item.name}` : `${item.name} indisponível`);
  inner.addEventListener('click', () => openConfirmDialog(item.id));

  const icon = document.createElement('div');
  icon.className = 'card-top-icon';
  icon.textContent = item.units > 0 ? '✓' : '!';
  inner.append(icon);

  const img = document.createElement('img');
  img.className = 'coffee-image';
  img.src = item.image;
  img.alt = item.name;
  img.loading = 'eager';
  img.decoding = 'async';

  const name = document.createElement('div');
  name.className = 'coffee-name';
  name.textContent = item.name;

  const stock = document.createElement('div');
  stock.className = 'stock-count';
  stock.textContent = `${item.units} unidades`;

  const status = document.createElement('div');
  status.className = 'stock-status';
  status.textContent = level.label;

  inner.append(img, name, stock, status);
  article.append(inner, createThermometer(item));
  return article;
}

function renderHome(data = getCurrentCoffees()) {
  const grid = document.getElementById('coffeeGrid');
  if (!grid) return;
  grid.innerHTML = '';
  data.forEach(item => grid.appendChild(createPublicCard(item)));

  const availability = document.getElementById('publicAvailability');
  const lastUpdated = document.getElementById('lastUpdated');
  if (availability) availability.textContent = getAvailableText(data);
  if (lastUpdated) lastUpdated.textContent = formatUpdatedAt();
}

function openConfirmDialog(coffeeId) {
  const data = getCurrentCoffees();
  const item = data.find(coffee => String(coffee.id) === String(coffeeId));
  const dialog = document.getElementById('confirmDialog');
  const message = document.getElementById('confirmMessage');

  if (!item || item.units <= 0 || !dialog || !message) return;

  pendingCoffeeId = item.id;
  message.textContent = `Confirmar ${item.name}? Depois da confirmação, restarão ${item.units - 1} unidades.`;
  dialog.showModal();
}

async function confirmCoffeeChoice() {
  if (pendingCoffeeId === null) return;

  const data = getCurrentCoffees();
  const item = data.find(coffee => String(coffee.id) === String(pendingCoffeeId));

  if (item && item.units > 0) {
    const originalUnits = item.units;
    item.units -= 1;
    cacheCoffees(data);
    renderHome(data);

    try {
      const latest = await updateCoffeeUnits(item.id, item.units, originalUnits);
      renderHome(latest);
    } catch (error) {
      item.units = originalUnits;
      cacheCoffees(data);
      renderHome(data);
      showToast('Nao foi possivel confirmar o cafe');
      console.warn('Erro ao confirmar cafe:', error);
    }
  }

  pendingCoffeeId = null;
}

function createAdminItem(item) {
  const article = document.createElement('article');
  article.className = 'admin-item stock-admin-item';

  const img = document.createElement('img');
  img.className = 'admin-thumb';
  img.src = item.image;
  img.alt = item.name;

  const info = document.createElement('div');
  info.className = 'admin-info';

  const name = document.createElement('p');
  name.className = 'admin-name';
  name.textContent = item.name;

  const meta = document.createElement('p');
  meta.className = 'admin-meta';
  meta.textContent = getLevel(item).label;

  info.append(name, meta);

  const unitsLabel = document.createElement('label');
  unitsLabel.className = 'admin-units-field';

  const labelText = document.createElement('span');
  labelText.textContent = 'Unidades';

  const input = document.createElement('input');
  input.type = 'number';
  input.min = '0';
  input.step = '1';
  input.value = item.units;
  input.setAttribute('aria-label', `Unidades de ${item.name}`);
  const syncUnits = () => {
    item.units = normalizeUnits(input.value);
    input.value = item.units;
    meta.textContent = getLevel(item).label;
    updateAdminSummary();
  };
  input.addEventListener('input', syncUnits);
  input.addEventListener('change', syncUnits);

  unitsLabel.append(labelText, input);
  article.append(img, info, unitsLabel);
  return article;
}

function updateAdminSummary() {
  const availability = document.getElementById('adminAvailability');
  if (availability) availability.textContent = getStockText(adminData);
}

function showToast(message) {
  let toast = document.querySelector('.toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.className = 'toast';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove('show'), 1800);
}

function renderAdminGrid() {
  const grid = document.getElementById('adminGrid');
  if (!grid) return;
  grid.innerHTML = '';
  adminData.forEach(item => grid.appendChild(createAdminItem(item)));
  updateAdminSummary();
}

function addCoffee(name, units) {
  const cleanName = name.trim();
  if (!cleanName) return;

  const existing = adminData.find(item => item.name.toLocaleLowerCase('pt-BR') === cleanName.toLocaleLowerCase('pt-BR'));
  if (existing) {
    existing.units = units;
    return;
  }

  adminData.push({
    id: createId(),
    name: cleanName,
    image: EMPTY_COFFEE_IMAGE,
    units
  });
}

async function renderAdmin() {
  const grid = document.getElementById('adminGrid');
  if (!grid) return;
  adminData = await loadCoffees();
  renderAdminGrid();

  const saveBtn = document.getElementById('saveBtn');
  if (saveBtn) saveBtn.onclick = async () => {
    saveBtn.disabled = true;
    try {
      adminData = await persistCoffees(adminData);
      renderAdminGrid();
      showToast('Estoque salvo com sucesso');
    } catch (error) {
      showToast('Nao foi possivel salvar');
      console.warn('Erro ao salvar estoque:', error);
    } finally {
      saveBtn.disabled = false;
    }
  };

  const form = document.getElementById('coffeeForm');
  if (form) form.onsubmit = async event => {
    event.preventDefault();
    const nameInput = document.getElementById('coffeeName');
    const unitsInput = document.getElementById('coffeeUnits');
    addCoffee(nameInput.value, normalizeUnits(unitsInput.value));
    renderAdminGrid();

    try {
      adminData = await persistCoffees(adminData);
      form.reset();
      nameInput.focus();
      renderAdminGrid();
      showToast('Cafe cadastrado');
    } catch (error) {
      showToast('Nao foi possivel cadastrar');
      console.warn('Erro ao cadastrar cafe:', error);
    }
  };
}

function initLogin() {
  const form = document.getElementById('loginForm');
  if (!form) return;
  form.addEventListener('submit', event => {
    event.preventDefault();
    const user = document.getElementById('user').value.trim();
    const password = document.getElementById('password').value.trim();
    if (user === 'admin' && password === 'admin') {
      window.location.href = 'admin.html';
      return;
    }
    alert('Usuário ou senha inválidos.');
  });
}

function initDialog() {
  const dialog = document.getElementById('confirmDialog');
  const confirmButton = document.getElementById('confirmCoffeeBtn');
  if (!dialog || !confirmButton) return;

  confirmButton.addEventListener('click', confirmCoffeeChoice);
  dialog.addEventListener('close', () => {
    if (dialog.returnValue !== 'confirm') pendingCoffeeId = null;
  });
}

async function refreshPageData(page) {
  const data = await loadCoffees();
  if (page === 'home') renderHome(data);
  if (page === 'admin') {
    adminData = cloneState(data);
    renderAdminGrid();
  }
}

function subscribeToCoffeeChanges(page) {
  const client = getSupabaseClient();
  if (!client) return;

  if (realtimeChannel) client.removeChannel(realtimeChannel);
  realtimeChannel = client
    .channel('public-coffees')
    .on('postgres_changes', { event: '*', schema: 'public', table: SUPABASE_TABLE }, () => {
      refreshPageData(page).catch(error => console.warn('Erro ao atualizar cafe:', error));
    })
    .subscribe();

  clearInterval(refreshTimer);
  refreshTimer = setInterval(() => {
    refreshPageData(page).catch(error => console.warn('Erro ao sincronizar cafe:', error));
  }, 15000);
}

async function init() {
  const page = document.body.dataset.page;
  if (!localStorage.getItem(STORAGE_KEY)) saveCoffees(getDefaultCoffees());
  if (page === 'home') {
    initDialog();
    renderHome(await loadCoffees());
    subscribeToCoffeeChanges(page);
  }
  if (page === 'admin') {
    await renderAdmin();
    subscribeToCoffeeChanges(page);
  }
  if (page === 'login') initLogin();
}

document.addEventListener('DOMContentLoaded', init);
